function Button({ children, onClick, variant = 'primary', full, disabled, icon: Icon, size = 'md', type = 'button' }) {
  const base = 'inline-flex items-center justify-center gap-2 font-semibold rounded-xl transition active:scale-[0.98] disabled:opacity-40';
  const sizes = size === 'sm' ? 'px-3 py-2 text-sm' : 'px-4 py-3 text-[15px]';
  const variants = {
    primary: { background: 'var(--gdc-yellow)', color: 'var(--gdc-black)' },
    dark: { background: 'var(--gdc-black)', color: 'var(--gdc-yellow)' },
    outline: { background: 'transparent', color: 'var(--gdc-black)', border: '1.5px solid rgba(11,11,12,0.18)' },
    ghost: { background: 'rgba(11,11,12,0.05)', color: 'var(--gdc-black)' },
    danger: { background: 'rgba(239,68,68,0.1)', color: '#B91C1C' },
  };
  return (
    <button type={type} onClick={onClick} disabled={disabled} className={`${base} ${sizes} ${full ? 'w-full' : ''}`} style={variants[variant]}>
      {Icon && <Icon size={size === 'sm' ? 15 : 17} />}
      {children}
    </button>
  );
}

