/* ---------------------------- App root: auth ---------------------------- */

export default function App() {
  const [booting, setBooting] = useState(true);
  const [session, setSession] = useState(null); // {accessToken, refreshToken, userId, email}
  const [profile, setProfile] = useState(null);
  const [profileError, setProfileError] = useState('');

  const loadProfile = useCallback(async (sess) => {
    try {
      const rows = await pg(`/profiles?id=eq.${sess.userId}&select=*`, sess.accessToken);
      setProfile(rows && rows[0] ? rows[0] : null);
      setProfileError('');
    } catch (e) {
      setProfileError(e.message);
    }
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const saved = localStorage.getItem(REFRESH_KEY);
        if (saved) {
          const json = await authRequest('/token?grant_type=refresh_token', { refresh_token: saved });
          const sess = { accessToken: json.access_token, refreshToken: json.refresh_token, userId: json.user.id, email: json.user.email };
          setSession(sess);
          localStorage.setItem(REFRESH_KEY, json.refresh_token);
          await loadProfile(sess);
        }
      } catch (_) {
        try { localStorage.removeItem(REFRESH_KEY); } catch (_) {}
      } finally {
        setBooting(false);
      }
    })();
  }, [loadProfile]);

  const handleAuthed = async (json) => {
    const sess = { accessToken: json.access_token, refreshToken: json.refresh_token, userId: json.user.id, email: json.user.email };
    setSession(sess);
    try { localStorage.setItem(REFRESH_KEY, json.refresh_token); } catch (_) {}
    await loadProfile(sess);
  };

  const logout = async () => {
    setSession(null);
    setProfile(null);
    try { localStorage.removeItem(REFRESH_KEY); } catch (_) {}
  };

  if (booting) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: 'var(--gdc-black)' }}>
        <GlobalStyle />
        <div className="flex flex-col items-center gap-3"><Crest size={56} /><div className="text-sm" style={{ color: 'var(--gdc-yellow)' }}>A carregar…</div></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen" style={{ background: 'var(--gdc-bg)', fontFamily: 'var(--font-body)' }}>
      <GlobalStyle />
      <div className="max-w-[480px] mx-auto min-h-screen relative pb-20" style={{ background: 'var(--gdc-bg)' }}>
        {!session ? (
          <AuthScreen onAuthed={handleAuthed} />
        ) : !profile ? (
          <div className="px-5 pt-10">
            <ErrorBlock message={profileError || 'A preparar o teu perfil…'} />
            <Button full variant="outline" icon={RefreshCw} onClick={() => loadProfile(session)}>Tentar novamente</Button>
            <div className="mt-2"><Button full variant="ghost" icon={LogOut} onClick={logout}>Sair</Button></div>
          </div>
        ) : profile.role === 'pending' ? (
          <PendingRoleScreen profile={profile} onLogout={logout} onRefresh={() => loadProfile(session)} />
        ) : (
          <AuthedApp session={session} profile={profile} onLogout={logout} onProfileChange={() => loadProfile(session)} />
        )}
      </div>
    </div>
  );
}

