/* ---------------------------- Auth screens ---------------------------- */

function AuthScreen({ onAuthed }) {
  const [mode, setMode] = useState('login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [password2, setPassword2] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');

  const submit = async () => {
    setError(''); setInfo('');
    if (mode === 'signup' && password !== password2) {
      setError('As palavras-passe não coincidem.');
      return;
    }
    setLoading(true);
    try {
      if (mode === 'signup') {
        const submittedEmail = email.trim();
        const json = await authRequest('/signup', { email: submittedEmail, password, data: { name: name.trim() } });
        if (json.access_token) {
          await onAuthed(json);
        } else {
          setName(''); setEmail(''); setPassword(''); setPassword2('');
          setMode('login');
          setInfo(`Falta um passo: enviámos um email de confirmação para ${submittedEmail}. Abre esse email e clica no link para ativar a conta — só depois consegues entrar.`);
        }
      } else {
        const json = await authRequest('/token?grant_type=password', { email: email.trim(), password });
        await onAuthed(json);
      }
    } catch (e) {
      setError(e.message === 'Invalid login credentials' ? 'Email ou palavra-passe incorretos.' : e.message);
    } finally {
      setLoading(false);
    }
  };

  const canSubmit = email.trim() && password.length >= 6 && (mode === 'login' || (name.trim() && password2.length >= 6));

  return (
    <div className="min-h-screen flex flex-col" style={{ background: 'var(--gdc-black)' }}>
      <div className="flex flex-col items-center pt-14 pb-8 px-6">
        <Crest size={72} />
        <div style={{ fontFamily: 'var(--font-display)' }} className="text-white text-2xl font-extrabold mt-4 text-center leading-tight tracking-wide">Gestão de Atletas da Formação</div>
        <div className="text-sm font-semibold mt-1" style={{ color: 'var(--gdc-yellow)' }}>Grupo Desportivo de Calvão</div>
      </div>

      <div className="flex-1 rounded-t-3xl px-5 pt-6 pb-8" style={{ background: 'var(--gdc-bg)' }}>
        <div className="flex gap-2 mb-5">
          <button onClick={() => setMode('login')} className="flex-1 py-2.5 rounded-lg text-sm font-bold flex items-center justify-center gap-1.5" style={{ background: mode === 'login' ? 'var(--gdc-yellow)' : 'rgba(11,11,12,0.05)' }}><LogIn size={15} />Entrar</button>
          <button onClick={() => setMode('signup')} className="flex-1 py-2.5 rounded-lg text-sm font-bold flex items-center justify-center gap-1.5" style={{ background: mode === 'signup' ? 'var(--gdc-yellow)' : 'rgba(11,11,12,0.05)' }}><UserPlus size={15} />Criar conta</button>
        </div>

        <ErrorBlock message={error} />
        {info && <div className="p-3 rounded-xl mb-3 text-sm" style={{ background: 'rgba(255,199,44,0.15)', color: 'var(--gdc-yellow-deep)' }}>{info}</div>}

        {mode === 'signup' && (
          <Field label="O teu nome">
            <input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder="Nome completo" />
          </Field>
        )}
        <Field label="Email">
          <div className="relative">
            <Mail size={15} className="absolute left-3 top-1/2 -translate-y-1/2" color="var(--gdc-grey)" />
            <input style={{ ...inputStyle, paddingLeft: 34 }} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="nome@email.com" />
          </div>
        </Field>
        <Field label="Palavra-passe">
          <div className="relative">
            <Lock size={15} className="absolute left-3 top-1/2 -translate-y-1/2" color="var(--gdc-grey)" />
            <input style={{ ...inputStyle, paddingLeft: 34 }} type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Mínimo 6 caracteres" onKeyDown={(e) => e.key === 'Enter' && canSubmit && submit()} />
          </div>
        </Field>
        {mode === 'signup' && (
          <Field label="Confirmar palavra-passe">
            <div className="relative">
              <Lock size={15} className="absolute left-3 top-1/2 -translate-y-1/2" color="var(--gdc-grey)" />
              <input style={{ ...inputStyle, paddingLeft: 34 }} type="password" value={password2} onChange={(e) => setPassword2(e.target.value)} placeholder="Repete a palavra-passe" onKeyDown={(e) => e.key === 'Enter' && canSubmit && submit()} />
            </div>
          </Field>
        )}

        <Button full disabled={!canSubmit || loading} onClick={submit} icon={mode === 'login' ? LogIn : UserPlus}>
          {loading ? 'Um momento…' : mode === 'login' ? 'Entrar' : 'Criar conta'}
        </Button>

        <div className="mt-6 text-xs text-center leading-relaxed" style={{ color: 'var(--gdc-grey)' }}>
          {mode === 'signup'
            ? 'Depois de criares a conta, pede ao administrador do clube para te atribuir a função de treinador ou de encarregado de educação.'
            : 'Esqueceste a palavra-passe? Por agora, pede ao administrador para te ajudar (recuperação por email ainda não está configurada).'}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------- Authed shell ---------------------------- */

function AuthedApp({ session, profile, onLogout, onProfileChange }) {
  const [route, setRoute] = useState({ screen: 'home' });
  const [pendingCount, setPendingCount] = useState(0);

  const refreshPendingCount = useCallback(async () => {
    if (profile.role !== 'admin') return;
    try {
      const rows = await pg(`/profiles?role=eq.pending&select=id`, session.accessToken);
      setPendingCount(rows.length);
    } catch (_) {}
  }, [session, profile.role]);

  useEffect(() => {
    refreshPendingCount();
    if (profile.role !== 'admin') return;
    const id = setInterval(refreshPendingCount, 20000);
    return () => clearInterval(id);
  }, [refreshPendingCount, profile.role]);

  const tabs = {
    admin: [
      { key: 'home', label: 'Equipas', icon: Trophy },
      { key: 'users', label: 'Utilizadores', icon: Users, badge: pendingCount },
    ],
    coach: [
      { key: 'home', label: 'Atletas', icon: Users },
      { key: 'events', label: 'Calendário', icon: Calendar },
      { key: 'reports', label: 'Relatórios', icon: PieChart },
    ],
    parent: [
      { key: 'home', label: 'Assiduidade', icon: ClipboardCheck },
      { key: 'calendar', label: 'Calendário', icon: Calendar },
      { key: 'behavior', label: 'Comportamento', icon: MessageSquareWarning },
    ],
  }[profile.role] || [];

  const roleLabel = { admin: 'Administrador', coach: 'Treinador', parent: 'Encarregado de Educação' };

  return (
    <div className="pb-4">
      <div className="flex items-center justify-between px-4 pt-2 pb-1" style={{ background: 'var(--gdc-black)' }}>
        <div className="flex items-center gap-2 py-2">
          <Crest size={30} />
          <div>
            <div className="text-white text-xs font-bold leading-none">{profile.name}</div>
            <div className="text-[10px] leading-none mt-1" style={{ color: 'var(--gdc-yellow)' }}>{roleLabel[profile.role]}</div>
          </div>
        </div>
        <button onClick={onLogout} className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: 'rgba(255,255,255,0.08)' }} title="Sair">
          <LogOut size={14} color="#fff" />
        </button>
      </div>

      <div>
        {profile.role === 'admin' && <AdminArea session={session} route={route} setRoute={setRoute} onPendingChange={refreshPendingCount} />}
        {profile.role === 'coach' && <CoachArea session={session} profile={profile} route={route} setRoute={setRoute} />}
        {profile.role === 'parent' && <ParentArea session={session} profile={profile} route={route} setRoute={setRoute} />}
      </div>

      {tabs.length > 0 && (
        <div className="fixed bottom-0 left-0 right-0 max-w-[480px] mx-auto flex border-t" style={{ background: '#fff', borderColor: 'rgba(11,11,12,0.08)' }}>
          {tabs.map((t) => {
            const active = route.screen === t.key || (t.key === 'home' && !['events', 'reports', 'behavior', 'users', 'calendar'].includes(route.screen));
            return (
              <button key={t.key} onClick={() => setRoute({ screen: t.key })} className="flex-1 flex flex-col items-center gap-0.5 py-2.5">
                <div className="relative">
                  <t.icon size={19} color={active ? 'var(--gdc-yellow-deep)' : 'var(--gdc-grey)'} />
                  {!!t.badge && (
                    <span className="absolute -top-1.5 -right-2 min-w-[16px] h-4 px-1 rounded-full flex items-center justify-center text-[9px] font-bold text-white" style={{ background: '#EF4444' }}>
                      {t.badge > 9 ? '9+' : t.badge}
                    </span>
                  )}
                </div>
                <span className="text-[10px] font-bold" style={{ color: active ? 'var(--gdc-yellow-deep)' : 'var(--gdc-grey)' }}>{t.label}</span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ---------------------------- Admin ---------------------------- */

function AdminArea({ session, route, setRoute, onPendingChange }) {
  const [teams, setTeams] = useState(null);
  const [athleteCounts, setAthleteCounts] = useState({});
  const [error, setError] = useState('');
  const [showNewTeam, setShowNewTeam] = useState(false);

  const load = useCallback(async () => {
    setError('');
    try {
      const t = await pg(`/teams?select=*,team_coaches(profiles(name))&order=name`, session.accessToken);
      setTeams(t);
      const ath = await pg(`/athletes?select=id,team_id`, session.accessToken);
      const counts = {};
      (ath || []).forEach((a) => { counts[a.team_id] = (counts[a.team_id] || 0) + 1; });
      setAthleteCounts(counts);
    } catch (e) { setError(e.message); }
  }, [session]);

  useEffect(() => { load(); }, [load]);

  if (route.screen === 'team' && route.teamId) {
    return <AdminTeamDetail session={session} teamId={route.teamId} onBack={() => { setRoute({ screen: 'home' }); load(); }} />;
  }
  if (route.screen === 'users') {
    return <AdminUsersTab session={session} onPendingChange={onPendingChange} />;
  }

  const createTeam = async ({ teamName }) => {
    await pg('/teams', session.accessToken, { method: 'POST', body: { name: teamName }, prefer: 'return=representation' });
    setShowNewTeam(false);
    load();
  };

  return (
    <div className="px-4 pt-4">
      <div className="flex items-center justify-between mb-3">
        <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold">Equipas</div>
        <Button size="sm" icon={Plus} onClick={() => setShowNewTeam(true)}>Nova equipa</Button>
      </div>
      <ErrorBlock message={error} />
      {teams === null ? <LoadingBlock /> : teams.length === 0 ? (
        <Empty icon={Trophy} title="Ainda sem equipas" hint="Cria a primeira equipa. Depois atribui um treinador no separador Utilizadores." action={<Button icon={Plus} onClick={() => setShowNewTeam(true)}>Criar equipa</Button>} />
      ) : (
        <div className="flex flex-col gap-2.5">
          {teams.map((t) => {
            const coachNames = (t.team_coaches || []).map((tc) => tc.profiles?.name).filter(Boolean);
            return (
              <Card key={t.id} onClick={() => setRoute({ screen: 'team', teamId: t.id })}>
                <div className="flex items-center justify-between">
                  <div>
                    <div className="font-bold" style={{ color: 'var(--gdc-black)' }}>{t.name}</div>
                    <div className="text-xs mt-1" style={{ color: 'var(--gdc-grey)' }}>
                      {coachNames.join(', ') || 'Sem treinador confirmado'} · {athleteCounts[t.id] || 0} atleta{(athleteCounts[t.id] || 0) === 1 ? '' : 's'}
                    </div>
                  </div>
                  <ChevronRight size={18} color="var(--gdc-grey)" />
                </div>
              </Card>
            );
          })}
        </div>
      )}
      {showNewTeam && <NewTeamModal onClose={() => setShowNewTeam(false)} onCreate={createTeam} />}
    </div>
  );
}

function NewTeamModal({ onClose, onCreate }) {
  const [teamName, setTeamName] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const submit = async () => {
    setSaving(true); setError('');
    try { await onCreate({ teamName: teamName.trim() }); }
    catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  return (
    <Modal title="Nova equipa" onClose={onClose}>
      <ErrorBlock message={error} />
      <Field label="Nome da equipa (ex: Sub-11)"><input style={inputStyle} value={teamName} onChange={(e) => setTeamName(e.target.value)} placeholder="Sub-11" /></Field>
      <div className="text-xs mb-3" style={{ color: 'var(--gdc-grey)' }}>Depois de criar, atribui um treinador no separador "Utilizadores".</div>
      <Button full disabled={!teamName.trim() || saving} onClick={submit}>{saving ? 'A criar…' : 'Criar equipa'}</Button>
    </Modal>
  );
}

function AdminTeamDetail({ session, teamId, onBack }) {
  const [team, setTeam] = useState(null);
  const [coaches, setCoaches] = useState([]);
  const [athletes, setAthletes] = useState([]);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [existingParents, setExistingParents] = useState([]);
  const [showAddCoach, setShowAddCoach] = useState(false);
  const [assignAthlete, setAssignAthlete] = useState(null);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setError('');
    try {
      const [teamRows, tc, ath, pending, parents] = await Promise.all([
        pg(`/teams?id=eq.${teamId}&select=*`, session.accessToken),
        pg(`/team_coaches?team_id=eq.${teamId}&select=profiles(id,name)`, session.accessToken),
        pg(`/athletes?team_id=eq.${teamId}&select=*,profiles(name)`, session.accessToken),
        pg(`/profiles?role=eq.pending&select=id,name&order=name`, session.accessToken),
        pg(`/profiles?role=eq.parent&select=id,name&order=name`, session.accessToken),
      ]);
      setTeam(teamRows[0]);
      setCoaches(tc.map((r) => r.profiles).filter(Boolean));
      setAthletes(ath);
      setPendingUsers(pending);
      setExistingParents(parents);
    } catch (e) { setError(e.message); }
  }, [session, teamId]);

  useEffect(() => { load(); }, [load]);

  const addCoach = async (userId) => {
    await pg('/team_coaches', session.accessToken, { method: 'POST', body: { team_id: teamId, coach_id: userId }, prefer: 'return=representation' });
    await pg(`/profiles?id=eq.${userId}`, session.accessToken, { method: 'PATCH', body: { role: 'coach' } });
    setShowAddCoach(false);
    load();
  };

  const assignParentToAthlete = async (userId, alreadyParent) => {
    await pg(`/athletes?id=eq.${assignAthlete.id}`, session.accessToken, { method: 'PATCH', body: { parent_id: userId } });
    if (!alreadyParent) {
      await pg(`/profiles?id=eq.${userId}`, session.accessToken, { method: 'PATCH', body: { role: 'parent' } });
    }
    setAssignAthlete(null);
    load();
  };

  if (!team) return <div className="px-4 pt-6"><ErrorBlock message={error} /><LoadingBlock /></div>;

  return (
    <div>
      <TopBar title={team.name} subtitle={`${athletes.length} atletas`} onBack={onBack} />
      <div className="px-4 pt-4">
        <ErrorBlock message={error} />
        <div className="flex items-center justify-between mb-2">
          <div className="font-bold text-sm" style={{ color: 'var(--gdc-black)' }}>Treinadores</div>
          <Button size="sm" variant="ghost" icon={Plus} onClick={() => setShowAddCoach(true)}>Adicionar</Button>
        </div>
        <div className="flex flex-col gap-2 mb-4">
          {coaches.map((c) => (
            <Card key={c.id}>
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: 'rgba(255,199,44,0.2)' }}><Dumbbell size={16} color="var(--gdc-yellow-deep)" /></div>
                <div className="font-semibold text-sm">{c.name}</div>
              </div>
            </Card>
          ))}
          {coaches.length === 0 && <div className="text-sm py-2" style={{ color: 'var(--gdc-grey)' }}>Sem treinadores ainda.</div>}
        </div>

        <div className="font-bold text-sm mb-2" style={{ color: 'var(--gdc-black)' }}>Atletas</div>
        {athletes.length === 0 ? (
          <div className="text-sm py-6 text-center" style={{ color: 'var(--gdc-grey)' }}>Sem atletas ainda. Os treinadores podem adicioná-los.</div>
        ) : (
          <div className="flex flex-col gap-2">
            {athletes.map((a) => (
              <Card key={a.id}>
                <div className="flex items-center justify-between gap-2">
                  <div className="min-w-0">
                    <div className="font-semibold text-sm">{a.name}</div>
                    <div className="text-xs mt-0.5 truncate" style={{ color: 'var(--gdc-grey)' }}>Enc. educação: {a.profiles?.name || 'Por atribuir'}</div>
                  </div>
                  <Button size="sm" variant="ghost" onClick={() => setAssignAthlete(a)}>{a.profiles?.name ? 'Mudar' : 'Atribuir'}</Button>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>
      {showAddCoach && (
        <Modal title="Atribuir treinador" onClose={() => setShowAddCoach(false)}>
          <AssignFromPendingForm
            pendingUsers={pendingUsers}
            emptyHint="Ninguém à espera de função. A pessoa tem de criar conta primeiro."
            buttonLabel="Atribuir como treinador"
            onSubmit={addCoach}
          />
        </Modal>
      )}
      {assignAthlete && (
        <Modal title={`Encarregado de educação de ${assignAthlete.name}`} onClose={() => setAssignAthlete(null)}>
          <AssignParentForm
            existingParents={existingParents}
            pendingUsers={pendingUsers}
            onSubmit={assignParentToAthlete}
          />
        </Modal>
      )}
    </div>
  );
}

function AssignParentForm({ existingParents, pendingUsers, onSubmit }) {
  const [mode, setMode] = useState(existingParents.length > 0 ? 'existing' : 'pending');
  const [userId, setUserId] = useState((existingParents[0] || pendingUsers[0])?.id || '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const list = mode === 'existing' ? existingParents : pendingUsers;

  const switchMode = (m) => {
    setMode(m);
    const l = m === 'existing' ? existingParents : pendingUsers;
    setUserId(l[0]?.id || '');
  };

  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit(userId, mode === 'existing'); } catch (e) { setError(e.message); } finally { setSaving(false); }
  };

  if (existingParents.length === 0 && pendingUsers.length === 0) {
    return <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Ainda não há nenhum encarregado de educação com conta criada (nem pendente). Pede à pessoa para criar conta primeiro.</div>;
  }

  return (
    <div>
      <ErrorBlock message={error} />
      <div className="flex gap-2 mb-3">
        <button onClick={() => switchMode('existing')} disabled={existingParents.length === 0} className="flex-1 py-2 rounded-lg text-sm font-semibold disabled:opacity-40" style={{ background: mode === 'existing' ? 'var(--gdc-yellow)' : 'rgba(11,11,12,0.05)' }}>Já é encarregado de outro atleta</button>
        <button onClick={() => switchMode('pending')} disabled={pendingUsers.length === 0} className="flex-1 py-2 rounded-lg text-sm font-semibold disabled:opacity-40" style={{ background: mode === 'pending' ? 'var(--gdc-yellow)' : 'rgba(11,11,12,0.05)' }}>Conta por atribuir</button>
      </div>
      {list.length === 0 ? (
        <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Sem opções nesta categoria.</div>
      ) : (
        <Field label="Pessoa">
          <select style={inputStyle} value={userId} onChange={(e) => setUserId(e.target.value)}>
            {list.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
          </select>
        </Field>
      )}
      <Button full disabled={!userId || saving || list.length === 0} onClick={submit}>{saving ? 'A atribuir…' : 'Atribuir'}</Button>
    </div>
  );
}

function AssignFromPendingForm({ pendingUsers, emptyHint, buttonLabel, onSubmit }) {
  const [userId, setUserId] = useState(pendingUsers[0]?.id || '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit(userId); } catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  if (pendingUsers.length === 0) {
    return <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>{emptyHint}</div>;
  }
  return (
    <div>
      <ErrorBlock message={error} />
      <Field label="Utilizador (já criou conta, sem função atribuída)">
        <select style={inputStyle} value={userId} onChange={(e) => setUserId(e.target.value)}>
          {pendingUsers.map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}
        </select>
      </Field>
      <Button full disabled={!userId || saving} onClick={submit}>{saving ? 'A atribuir…' : buttonLabel}</Button>
    </div>
  );
}

function AdminUsersTab({ session, onPendingChange }) {
  const [pending, setPending] = useState(null);
  const [teams, setTeams] = useState([]);
  const [athletes, setAthletes] = useState([]);
  const [error, setError] = useState('');
  const [assignTarget, setAssignTarget] = useState(null); // { user, type: 'coach'|'parent' }
  const [deleteTarget, setDeleteTarget] = useState(null);

  const load = useCallback(async () => {
    setError('');
    try {
      const [pend, tm, ath] = await Promise.all([
        pg(`/profiles?role=eq.pending&select=*&order=created_at`, session.accessToken),
        pg(`/teams?select=id,name&order=name`, session.accessToken),
        pg(`/athletes?select=id,name,teams(name)&order=name`, session.accessToken),
      ]);
      setPending(pend);
      setTeams(tm);
      setAthletes(ath);
    } catch (e) { setError(e.message); }
  }, [session]);

  useEffect(() => { load(); }, [load]);

  const assignCoach = async (userId, teamId) => {
    await pg('/team_coaches', session.accessToken, { method: 'POST', body: { team_id: teamId, coach_id: userId }, prefer: 'return=representation' });
    await pg(`/profiles?id=eq.${userId}`, session.accessToken, { method: 'PATCH', body: { role: 'coach' } });
    setAssignTarget(null);
    load();
    onPendingChange?.();
  };
  const assignParent = async (userId, athleteId) => {
    await pg(`/athletes?id=eq.${athleteId}`, session.accessToken, { method: 'PATCH', body: { parent_id: userId } });
    await pg(`/profiles?id=eq.${userId}`, session.accessToken, { method: 'PATCH', body: { role: 'parent' } });
    setAssignTarget(null);
    load();
    onPendingChange?.();
  };
  const deleteAccount = async () => {
    await pg(`/profiles?id=eq.${deleteTarget.id}`, session.accessToken, { method: 'DELETE' });
    setDeleteTarget(null);
    load();
    onPendingChange?.();
  };

  return (
    <div className="px-4 pt-4">
      <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold mb-1">Utilizadores</div>
      <div className="text-xs mb-4" style={{ color: 'var(--gdc-grey)' }}>Contas criadas à espera de função.</div>
      <ErrorBlock message={error} />
      {pending === null ? <LoadingBlock /> : pending.length === 0 ? (
        <Empty icon={Users} title="Sem contas por atribuir" hint="Assim que alguém criar conta, aparece aqui para lhe atribuíres uma função." />
      ) : (
        <div className="flex flex-col gap-2.5">
          {pending.map((u) => (
            <Card key={u.id}>
              <div className="flex items-center justify-between mb-2">
                <div className="font-semibold text-sm">{u.name}</div>
                <button onClick={() => setDeleteTarget(u)} className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: 'rgba(239,68,68,0.1)' }} title="Eliminar conta">
                  <Trash2 size={13} color="#B91C1C" />
                </button>
              </div>
              <div className="flex gap-2">
                <Button size="sm" variant="outline" full icon={Dumbbell} onClick={() => setAssignTarget({ user: u, type: 'coach' })}>Treinador</Button>
                <Button size="sm" variant="outline" full icon={Baby} onClick={() => setAssignTarget({ user: u, type: 'parent' })}>Enc. educação</Button>
              </div>
            </Card>
          ))}
        </div>
      )}

      {assignTarget?.type === 'coach' && (
        <Modal title={`Atribuir equipa a ${assignTarget.user.name}`} onClose={() => setAssignTarget(null)}>
          {teams.length === 0 ? (
            <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Cria primeiro uma equipa no separador "Equipas".</div>
          ) : (
            <TeamPicker teams={teams} onSubmit={(teamId) => assignCoach(assignTarget.user.id, teamId)} />
          )}
        </Modal>
      )}
      {assignTarget?.type === 'parent' && (
        <Modal title={`Ligar ${assignTarget.user.name} a um atleta`} onClose={() => setAssignTarget(null)}>
          {athletes.length === 0 ? (
            <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Ainda não há atletas criados. Pede a um treinador para criar o atleta primeiro.</div>
          ) : (
            <AthletePicker athletes={athletes} onSubmit={(athleteId) => assignParent(assignTarget.user.id, athleteId)} />
          )}
        </Modal>
      )}
      {deleteTarget && (
        <ConfirmModal
          title="Eliminar conta"
          message={`Tem a certeza que deseja eliminar a conta de "${deleteTarget.name}"? Esta pessoa deixa de aparecer no clube e, se voltar a entrar, terá de aguardar nova atribuição de função.`}
          onClose={() => setDeleteTarget(null)}
          onConfirm={deleteAccount}
        />
      )}
    </div>
  );
}

function TeamPicker({ teams, onSubmit }) {
  const [teamId, setTeamId] = useState(teams[0]?.id || '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit(teamId); } catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  return (
    <div>
      <ErrorBlock message={error} />
      <Field label="Equipa">
        <select style={inputStyle} value={teamId} onChange={(e) => setTeamId(e.target.value)}>
          {teams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
        </select>
      </Field>
      <Button full disabled={!teamId || saving} onClick={submit}>{saving ? 'A atribuir…' : 'Atribuir como treinador'}</Button>
    </div>
  );
}

function AthletePicker({ athletes, onSubmit }) {
  const [athleteId, setAthleteId] = useState(athletes[0]?.id || '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit(athleteId); } catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  return (
    <div>
      <ErrorBlock message={error} />
      <Field label="Atleta">
        <select style={inputStyle} value={athleteId} onChange={(e) => setAthleteId(e.target.value)}>
          {athletes.map((a) => <option key={a.id} value={a.id}>{a.name}{a.teams?.name ? ` · ${a.teams.name}` : ''}</option>)}
        </select>
      </Field>
      <Button full disabled={!athleteId || saving} onClick={submit}>{saving ? 'A atribuir…' : 'Atribuir como encarregado de educação'}</Button>
    </div>
  );
}

/* ---------------------------- Coach ---------------------------- */

function CoachArea({ session, profile, route, setRoute }) {
  const [myTeams, setMyTeams] = useState(null);
  const [teamId, setTeamId] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    (async () => {
      try {
        const rows = await pg(`/team_coaches?coach_id=eq.${profile.id}&select=team_id,teams(*)`, session.accessToken);
        const teams = rows.map((r) => r.teams).filter(Boolean);
        setMyTeams(teams);
        if (teams[0]) setTeamId((prev) => prev || teams[0].id);
      } catch (e) { setError(e.message); }
    })();
  }, [session, profile]);

  if (myTeams === null) return <div className="px-4 pt-6"><ErrorBlock message={error} /><LoadingBlock /></div>;
  const team = myTeams.find((t) => t.id === teamId) || myTeams[0];
  if (!team) return <div className="px-4 pt-6"><Empty icon={Trophy} title="Sem equipa associada" hint="Pede ao administrador para te atribuir a uma equipa." /></div>;

  const TeamSwitcher = myTeams.length > 1 ? (
    <div className="px-4 pt-3">
      <select style={inputStyle} value={team.id} onChange={(e) => setTeamId(e.target.value)}>
        {myTeams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
      </select>
    </div>
  ) : null;

  if (route.screen === 'athlete' && route.athleteId) {
    return <div>{TeamSwitcher}<AthleteDetail session={session} profile={profile} athleteId={route.athleteId} onBack={() => setRoute({ screen: 'home' })} /></div>;
  }
  if (route.screen === 'event' && route.eventId) {
    return <div>{TeamSwitcher}<AttendanceScreen session={session} eventId={route.eventId} teamId={team.id} onBack={() => setRoute({ screen: 'events' })} /></div>;
  }
  if (route.screen === 'events') {
    return <div>{TeamSwitcher}<EventsTab session={session} team={team} setRoute={setRoute} /></div>;
  }
  if (route.screen === 'reports') {
    return <div>{TeamSwitcher}<ReportsTab session={session} team={team} /></div>;
  }
  return <div>{TeamSwitcher}<AthletesTab session={session} team={team} setRoute={setRoute} /></div>;
}

function AthletesTab({ session, team, setRoute }) {
  const [athletes, setAthletes] = useState(null);
  const [error, setError] = useState('');
  const [showAdd, setShowAdd] = useState(false);

  const load = useCallback(async () => {
    setError('');
    try {
      const rows = await pg(`/athletes?team_id=eq.${team.id}&select=*,profiles(name)&order=name`, session.accessToken);
      setAthletes(rows);
    } catch (e) { setError(e.message); }
  }, [session, team]);

  useEffect(() => { load(); }, [load]);

  const [incidentCounts, setIncidentCounts] = useState({});
  useEffect(() => {
    (async () => {
      if (!athletes || athletes.length === 0) return;
      try {
        const ids = athletes.map((a) => a.id).join(',');
        const rows = await pg(`/incidents?athlete_id=in.(${ids})&select=id,athlete_id`, session.accessToken);
        const counts = {};
        (rows || []).forEach((r) => { counts[r.athlete_id] = (counts[r.athlete_id] || 0) + 1; });
        setIncidentCounts(counts);
      } catch (_) {}
    })();
  }, [athletes, session]);

  const addAthlete = async ({ name, birthYear }) => {
    const body = { team_id: team.id, name, birth_year: birthYear ? Number(birthYear) : null };
    await pg('/athletes', session.accessToken, { method: 'POST', body, prefer: 'return=representation' });
    setShowAdd(false);
    load();
  };

  return (
    <div className="px-4 pt-4">
      <div className="flex items-center justify-between mb-3">
        <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold">{team.name}</div>
        <Button size="sm" icon={Plus} onClick={() => setShowAdd(true)}>Atleta</Button>
      </div>
      <ErrorBlock message={error} />
      {athletes === null ? <LoadingBlock /> : athletes.length === 0 ? (
        <Empty icon={Users} title="Sem atletas" hint="Adiciona o primeiro atleta desta equipa." action={<Button icon={Plus} onClick={() => setShowAdd(true)}>Adicionar atleta</Button>} />
      ) : (
        <div className="flex flex-col gap-2">
          {athletes.map((a) => (
            <Card key={a.id} onClick={() => setRoute({ screen: 'athlete', athleteId: a.id })}>
              <div className="flex items-center justify-between">
                <div>
                  <div className="font-semibold text-sm">{a.name}{a.birth_year ? ` · ${a.birth_year}` : ''}</div>
                </div>
                <div className="flex items-center gap-2">
                  {incidentCounts[a.id] > 0 && <Badge tone="amber">{incidentCounts[a.id]} incid.</Badge>}
                  <ChevronRight size={16} color="var(--gdc-grey)" />
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
      {showAdd && <AddAthleteModal session={session} onClose={() => setShowAdd(false)} onSubmit={addAthlete} />}
    </div>
  );
}

function AddAthleteModal({ session, onClose, onSubmit }) {
  const [name, setName] = useState('');
  const [birthYear, setBirthYear] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const canSubmit = name.trim();

  const submit = async () => {
    setSaving(true); setError('');
    try {
      await onSubmit({ name: name.trim(), birthYear: birthYear.trim() });
    } catch (e) { setError(e.message); } finally { setSaving(false); }
  };

  return (
    <Modal title="Novo atleta" onClose={onClose}>
      <ErrorBlock message={error} />
      <Field label="Nome do atleta"><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder="Nome completo" /></Field>
      <Field label="Ano de nascimento (opcional)"><input style={inputStyle} value={birthYear} onChange={(e) => setBirthYear(e.target.value)} placeholder="2015" /></Field>
      <div className="text-xs mb-3" style={{ color: 'var(--gdc-grey)' }}>Depois de criares o atleta, pede ao administrador para lhe atribuir o encarregado de educação (separador "Utilizadores").</div>
      <Button full disabled={!canSubmit || saving} onClick={submit}>{saving ? 'A guardar…' : 'Adicionar atleta'}</Button>
    </Modal>
  );
}

function EventsTab({ session, team, setRoute }) {
  const [events, setEvents] = useState(null);
  const [error, setError] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const [athleteTotal, setAthleteTotal] = useState(0);
  const [presentByEvent, setPresentByEvent] = useState({});
  const [deleteTarget, setDeleteTarget] = useState(null);

  const load = useCallback(async () => {
    setError('');
    try {
      const rows = await pg(`/events?team_id=eq.${team.id}&select=*&order=date.desc`, session.accessToken);
      setEvents(rows);
      const ath = await pg(`/athletes?team_id=eq.${team.id}&select=id`, session.accessToken);
      setAthleteTotal(ath.length);
      if (rows.length > 0) {
        const ids = rows.map((e) => e.id).join(',');
        const att = await pg(`/attendance?event_id=in.(${ids})&present=eq.true&select=event_id`, session.accessToken);
        const counts = {};
        (att || []).forEach((a) => { counts[a.event_id] = (counts[a.event_id] || 0) + 1; });
        setPresentByEvent(counts);
      }
    } catch (e) { setError(e.message); }
  }, [session, team]);

  useEffect(() => { load(); }, [load]);

  const addEvent = async ({ type, date, label }) => {
    const [ev] = await pg('/events', session.accessToken, { method: 'POST', body: { team_id: team.id, type, date, label: label || type }, prefer: 'return=representation' });
    setShowAdd(false);
    if (ev.date <= todayISO()) {
      setRoute({ screen: 'event', eventId: ev.id });
    } else {
      load();
    }
  };

  const deleteEvent = async () => {
    await pg(`/events?id=eq.${deleteTarget.id}`, session.accessToken, { method: 'DELETE' });
    setDeleteTarget(null);
    load();
  };

  return (
    <div className="px-4 pt-4">
      <div className="flex items-center justify-between mb-3">
        <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold">Calendário</div>
        <Button size="sm" icon={CalendarPlus} onClick={() => setShowAdd(true)}>Novo</Button>
      </div>
      <ErrorBlock message={error} />
      {events === null ? <LoadingBlock /> : events.length === 0 ? (
        <Empty icon={Calendar} title="Sem treinos ou jogos" hint="Cria o primeiro evento para começar a marcar presenças." action={<Button icon={Plus} onClick={() => setShowAdd(true)}>Criar evento</Button>} />
      ) : (
        <div className="flex flex-col gap-2">
          {events.map((ev) => (
            <Card key={ev.id}>
              <div className="flex items-center justify-between">
                <div onClick={() => setRoute({ screen: 'event', eventId: ev.id })} className="flex items-center gap-3 flex-1 min-w-0 cursor-pointer">
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0" style={{ background: ev.type === 'Jogo' ? 'rgba(255,199,44,0.22)' : 'rgba(11,11,12,0.06)' }}>
                    {ev.type === 'Jogo' ? <Swords size={17} color="var(--gdc-yellow-deep)" /> : <Dumbbell size={17} color="var(--gdc-grey)" />}
                  </div>
                  <div className="min-w-0"><div className="font-semibold text-sm truncate">{ev.label}</div><div className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{fmtDate(ev.date)}</div></div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <Badge tone={ev.type === 'Jogo' ? 'yellow' : 'grey'}>{presentByEvent[ev.id] || 0}/{athleteTotal} presentes</Badge>
                  <button onClick={() => setDeleteTarget(ev)} className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: 'rgba(239,68,68,0.1)' }} title="Eliminar">
                    <Trash2 size={14} color="#B91C1C" />
                  </button>
                </div>
              </div>
            </Card>
          ))}
        </div>
      )}
      {showAdd && <NewEventModal onClose={() => setShowAdd(false)} onSubmit={addEvent} />}
      {deleteTarget && (
        <ConfirmModal
          title="Eliminar treino/jogo"
          message="Tem a certeza que deseja apagar este treino?"
          onClose={() => setDeleteTarget(null)}
          onConfirm={deleteEvent}
        />
      )}
    </div>
  );
}

function NewEventModal({ onClose, onSubmit }) {
  const [type, setType] = useState('Treino');
  const [date, setDate] = useState(todayISO());
  const [label, setLabel] = useState(() => defaultEventLabel('Treino', todayISO()));
  const [labelTouched, setLabelTouched] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!labelTouched) setLabel(defaultEventLabel(type, date));
  }, [type, date, labelTouched]);

  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit({ type, date, label: label.trim() || defaultEventLabel(type, date) }); }
    catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  return (
    <Modal title="Novo treino/jogo" onClose={onClose}>
      <ErrorBlock message={error} />
      <div className="flex gap-2 mb-3">
        {['Treino', 'Jogo'].map((t) => (
          <button key={t} onClick={() => setType(t)} className="flex-1 py-2.5 rounded-lg text-sm font-semibold" style={{ background: type === t ? 'var(--gdc-yellow)' : 'rgba(11,11,12,0.05)' }}>{t}</button>
        ))}
      </div>
      <Field label="Data"><input type="date" style={inputStyle} value={date} onChange={(e) => setDate(e.target.value)} /></Field>
      <Field label="Nome (editável, ex: 'vs Sporting')">
        <input style={inputStyle} value={label} onChange={(e) => { setLabel(e.target.value); setLabelTouched(true); }} placeholder={defaultEventLabel(type, date)} />
      </Field>
      <Button full disabled={!date || saving} onClick={submit}>{saving ? 'A criar…' : 'Criar'}</Button>
    </Modal>
  );
}

function AttendanceScreen({ session, eventId, teamId, onBack }) {
  const [ev, setEv] = useState(null);
  const [athletes, setAthletes] = useState([]);
  const [records, setRecords] = useState({});
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setError('');
    try {
      const [evRows, athRows, attRows] = await Promise.all([
        pg(`/events?id=eq.${eventId}&select=*`, session.accessToken),
        pg(`/athletes?team_id=eq.${teamId}&select=*&order=name`, session.accessToken),
        pg(`/attendance?event_id=eq.${eventId}&select=*`, session.accessToken),
      ]);
      setEv(evRows[0]);
      setAthletes(athRows);
      const map = {};
      (attRows || []).forEach((r) => { map[r.athlete_id] = r; });
      setRecords(map);
    } catch (e) { setError(e.message); }
  }, [session, eventId, teamId]);

  useEffect(() => { load(); }, [load]);

  const setRecord = async (athleteId, patch) => {
    const current = records[athleteId] || { present: false, behavior: null };
    const next = { ...current, ...patch };
    setRecords((prev) => ({ ...prev, [athleteId]: next }));
    try {
      await pg(`/attendance?on_conflict=event_id,athlete_id`, session.accessToken, {
        method: 'POST',
        body: { event_id: eventId, athlete_id: athleteId, present: next.present, behavior: next.behavior },
        prefer: 'resolution=merge-duplicates,return=representation',
      });
    } catch (e) { setError(e.message); }
  };

  const togglePresent = (athleteId) => {
    const rec = records[athleteId];
    const nextPresent = !(rec?.present);
    setRecord(athleteId, { present: nextPresent, behavior: nextPresent ? rec?.behavior || null : null });
  };

  if (!ev) return <div className="px-4 pt-6"><ErrorBlock message={error} /><LoadingBlock /></div>;
  const presentCount = athletes.filter((a) => records[a.id]?.present).length;
  const isFuture = ev.date > todayISO();

  return (
    <div>
      <TopBar title={ev.label} subtitle={`${fmtDate(ev.date)} · ${presentCount}/${athletes.length} presentes`} onBack={onBack} />
      <div className="px-4 pt-4">
        <ErrorBlock message={error} />
        {isFuture && (
          <div className="p-3 rounded-xl mb-3 text-sm" style={{ background: 'rgba(255,199,44,0.15)', color: 'var(--gdc-yellow-deep)' }}>
            Este treino/jogo ainda não aconteceu. A marcação de presenças e comportamento só fica disponível a partir da data do evento.
          </div>
        )}
        {athletes.length === 0 ? <Empty icon={Users} title="Sem atletas na equipa" /> : (
          <div className="flex flex-col gap-2">
            {athletes.map((a) => {
              const rec = records[a.id];
              const present = !!rec?.present;
              return (
                <Card key={a.id}>
                  <div className="flex items-center justify-between gap-3">
                    <button onClick={() => !isFuture && togglePresent(a.id)} disabled={isFuture} className="flex items-center gap-3 flex-1 min-w-0 text-left disabled:opacity-50">
                      <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0 transition" style={{ background: present ? '#22C55E' : 'rgba(11,11,12,0.08)' }}>
                        {present ? <Check size={17} color="#fff" /> : <X size={15} color="var(--gdc-grey)" />}
                      </div>
                      <div className="font-semibold text-sm truncate">{a.name}</div>
                    </button>
                  </div>
                  {present && !isFuture && <div className="mt-3"><SegBehavior value={rec?.behavior} onChange={(v) => setRecord(a.id, { behavior: v })} /></div>}
                </Card>
              );
            })}
          </div>
        )}
        <div className="text-xs text-center mt-4 mb-2" style={{ color: 'var(--gdc-grey)' }}>Toca no nome para marcar presença. Guardado automaticamente.</div>
      </div>
    </div>
  );
}

function ReportsTab({ session, team }) {
  const [month, setMonth] = useState(() => todayISO().slice(0, 7));
  const [athletes, setAthletes] = useState([]);
  const [events, setEvents] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      setLoading(true); setError('');
      try {
        const [start, end] = monthRange(month);
        const ath = await pg(`/athletes?team_id=eq.${team.id}&select=*&order=name`, session.accessToken);
        setAthletes(ath);
        const evs = await pg(`/events?team_id=eq.${team.id}&date=gte.${start}&date=lte.${end}&select=*`, session.accessToken);
        setEvents(evs);
        if (evs.length > 0) {
          const ids = evs.map((e) => e.id).join(',');
          const att = await pg(`/attendance?event_id=in.(${ids})&select=*`, session.accessToken);
          setAttendance(att);
        } else setAttendance([]);
        if (ath.length > 0) {
          const aids = ath.map((a) => a.id).join(',');
          const inc = await pg(`/incidents?athlete_id=in.(${aids})&date=gte.${start}&date=lte.${end}&select=id,athlete_id`, session.accessToken);
          setIncidents(inc);
        } else setIncidents([]);
      } catch (e) { setError(e.message); } finally { setLoading(false); }
    })();
  }, [session, team, month]);

  const today = todayISO();
  const pastEvents = events.filter((e) => e.date <= today);
  const pastEventIds = new Set(pastEvents.map((e) => e.id));

  return (
    <div className="px-4 pt-4">
      <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold mb-3">Relatórios</div>
      <MonthNav month={month} onChange={setMonth} />
      <ErrorBlock message={error} />
      {loading ? <LoadingBlock /> : events.length === 0 ? (
        <Empty icon={PieChart} title="Sem eventos neste mês" hint="Escolhe outro mês ou cria treinos/jogos primeiro." />
      ) : (
        <div className="flex flex-col gap-2.5">
          <div className="text-xs -mt-1 mb-1" style={{ color: 'var(--gdc-grey)' }}>Só conta treinos/jogos até hoje — eventos futuros não entram no cálculo de assiduidade.</div>
          {athletes.map((a) => {
            const records = attendance.filter((r) => r.athlete_id === a.id && pastEventIds.has(r.event_id));
            const presentCount = records.filter((r) => r.present).length;
            const pct = pastEvents.length ? Math.round((presentCount / pastEvents.length) * 100) : 0;
            const bom = records.filter((r) => r.behavior === 'Bom').length;
            const razo = records.filter((r) => r.behavior === 'Razoável').length;
            const mau = records.filter((r) => r.behavior === 'Mau').length;
            const incCount = incidents.filter((i) => i.athlete_id === a.id).length;
            return (
              <Card key={a.id}>
                <div className="flex items-center justify-between mb-2">
                  <div className="font-semibold text-sm">{a.name}</div>
                  <Badge tone={pct >= 75 ? 'green' : pct >= 50 ? 'amber' : 'red'}>{pct}% assiduidade</Badge>
                </div>
                <div className="h-2 rounded-full overflow-hidden mb-3" style={{ background: 'rgba(11,11,12,0.07)' }}>
                  <div className="h-full rounded-full" style={{ width: `${pct}%`, background: pct >= 75 ? '#22C55E' : pct >= 50 ? '#FB923C' : '#EF4444' }} />
                </div>
                <div className="flex items-center gap-3 text-xs flex-wrap" style={{ color: 'var(--gdc-grey)' }}>
                  <span>{presentCount}/{pastEvents.length} presenças</span><span>·</span>
                  <span>{bom} Bom / {razo} Razoável / {mau} Mau</span>
                  {incCount > 0 && <Badge tone="red">{incCount} incid.</Badge>}
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

function AthleteDetail({ session, profile, athleteId, onBack }) {
  const [athlete, setAthlete] = useState(null);
  const [records, setRecords] = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [error, setError] = useState('');
  const [showIncident, setShowIncident] = useState(false);

  const load = useCallback(async () => {
    setError('');
    try {
      const [athRows, attRows, incRows] = await Promise.all([
        pg(`/athletes?id=eq.${athleteId}&select=*,profiles(name)`, session.accessToken),
        pg(`/attendance?athlete_id=eq.${athleteId}&select=*,events(*)`, session.accessToken),
        pg(`/incidents?athlete_id=eq.${athleteId}&select=*&order=date.desc`, session.accessToken),
      ]);
      setAthlete(athRows[0]);
      const today = todayISO();
      setRecords((attRows || []).filter((r) => r.events && r.events.date <= today).sort((a, b) => (b.events.date || '').localeCompare(a.events.date || '')));
      setIncidents(incRows);
    } catch (e) { setError(e.message); }
  }, [session, athleteId]);

  useEffect(() => { load(); }, [load]);

  const addIncident = async (description) => {
    await pg('/incidents', session.accessToken, {
      method: 'POST',
      body: { athlete_id: athleteId, description, created_by: profile.id, created_by_role: 'coach' },
      prefer: 'return=representation',
    });
    setShowIncident(false);
    load();
  };

  if (!athlete) return <div className="px-4 pt-6"><ErrorBlock message={error} /><LoadingBlock /></div>;

  return (
    <div>
      <TopBar title={athlete.name} subtitle={`Enc. educação: ${athlete.profiles?.name || 'Por atribuir'}`} onBack={onBack} />
      <div className="px-4 pt-4">
        <ErrorBlock message={error} />
        <div className="flex items-center justify-between mb-2">
          <div className="font-bold text-sm">Incidências de comportamento</div>
          <Button size="sm" variant="ghost" icon={Plus} onClick={() => setShowIncident(true)}>Registar</Button>
        </div>
        {incidents.length === 0 ? <div className="text-sm py-4 text-center mb-4" style={{ color: 'var(--gdc-grey)' }}>Sem incidências registadas.</div> : (
          <div className="flex flex-col gap-2 mb-6">
            {incidents.map((i) => (
              <Card key={i.id}>
                <div className="flex items-center justify-between mb-1">
                  <Badge tone="amber">{fmtDate(i.date)}</Badge>
                  <span className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{i.created_by_role === 'parent' ? 'enc. educação' : 'treinador'}</span>
                </div>
                <div className="text-sm">{i.description}</div>
              </Card>
            ))}
          </div>
        )}

        <div className="font-bold text-sm mb-2">Histórico de presenças</div>
        {records.length === 0 ? <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Sem registos ainda.</div> : (
          <div className="flex flex-col gap-2">
            {records.map((r) => (
              <Card key={r.id}>
                <div className="flex items-center justify-between">
                  <div><div className="font-semibold text-sm">{r.events.label}</div><div className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{fmtDate(r.events.date)}</div></div>
                  <div className="flex items-center gap-1.5">
                    {r.present ? <Badge tone="green">Presente</Badge> : <Badge tone="grey">Ausente</Badge>}
                    {r.present && r.behavior && <Badge tone={r.behavior === 'Bom' ? 'green' : r.behavior === 'Razoável' ? 'amber' : 'red'}>{r.behavior}</Badge>}
                  </div>
                </div>
              </Card>
            ))}
          </div>
        )}
      </div>
      {showIncident && <IncidentModal onClose={() => setShowIncident(false)} onSubmit={addIncident} />}
    </div>
  );
}

function IncidentModal({ onClose, onSubmit }) {
  const [text, setText] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const submit = async () => {
    setSaving(true); setError('');
    try { await onSubmit(text.trim()); } catch (e) { setError(e.message); } finally { setSaving(false); }
  };
  return (
    <Modal title="Registar incidência" onClose={onClose}>
      <ErrorBlock message={error} />
      <Field label="Descrição">
        <textarea style={{ ...inputStyle, minHeight: 100, resize: 'vertical' }} value={text} onChange={(e) => setText(e.target.value)} placeholder="Ex: comportamento na escola, notas, atitude no treino…" />
      </Field>
      <Button full disabled={!text.trim() || saving} onClick={submit}>{saving ? 'A guardar…' : 'Guardar'}</Button>
    </Modal>
  );
}

/* ---------------------------- Parent ---------------------------- */

function ParentArea({ session, profile, route, setRoute }) {
  const [myKids, setMyKids] = useState(null);
  const [athleteId, setAthleteId] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    (async () => {
      try {
        const rows = await pg(`/athletes?parent_id=eq.${profile.id}&select=*,teams(*)`, session.accessToken);
        setMyKids(rows);
        if (rows[0]) setAthleteId((prev) => prev || rows[0].id);
      } catch (e) { setError(e.message); }
    })();
  }, [session, profile]);

  if (myKids === null) return <div className="px-4 pt-6"><ErrorBlock message={error} /><LoadingBlock /></div>;
  const athlete = myKids.find((a) => a.id === athleteId) || myKids[0];
  if (!athlete) return <div className="px-4 pt-6"><Empty icon={Baby} title="Sem atleta associado" hint="Pede ao administrador do clube para te ligar ao atleta." /></div>;

  const KidSwitcher = myKids.length > 1 ? (
    <div className="px-4 pt-3">
      <select style={inputStyle} value={athlete.id} onChange={(e) => setAthleteId(e.target.value)}>
        {myKids.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
      </select>
    </div>
  ) : null;

  return (
    <div>
      {KidSwitcher}
      {route.screen === 'behavior' ? (
        <ParentBehaviorTab session={session} profile={profile} athlete={athlete} />
      ) : route.screen === 'calendar' ? (
        <ParentCalendarTab session={session} athlete={athlete} />
      ) : (
        <ParentAttendanceTab session={session} athlete={athlete} />
      )}
    </div>
  );
}

function ParentCalendarTab({ session, athlete }) {
  const [events, setEvents] = useState(null);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setError('');
    try {
      const rows = await pg(`/events?team_id=eq.${athlete.team_id}&select=*&order=date.asc`, session.accessToken);
      setEvents(rows);
    } catch (e) { setError(e.message); }
  }, [session, athlete]);

  useEffect(() => { load(); }, [load]);

  const today = todayISO();

  return (
    <div className="px-4 pt-4">
      <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold mb-0.5">Calendário</div>
      <div className="text-xs mb-4" style={{ color: 'var(--gdc-grey)' }}>{athlete.teams?.name} · todos os treinos e jogos</div>
      <ErrorBlock message={error} />
      {events === null ? <LoadingBlock /> : events.length === 0 ? (
        <Empty icon={Calendar} title="Sem treinos ou jogos agendados" />
      ) : (
        <div className="flex flex-col gap-2">
          {events.map((ev) => {
            const isFuture = ev.date > today;
            return (
              <Card key={ev.id}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: ev.type === 'Jogo' ? 'rgba(255,199,44,0.22)' : 'rgba(11,11,12,0.06)' }}>
                      {ev.type === 'Jogo' ? <Swords size={15} color="var(--gdc-yellow-deep)" /> : <Dumbbell size={15} color="var(--gdc-grey)" />}
                    </div>
                    <div><div className="font-semibold text-sm">{ev.label}</div><div className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{fmtDate(ev.date)}</div></div>
                  </div>
                  {isFuture ? <Badge tone="yellow">Agendado</Badge> : <Badge tone="grey">Realizado</Badge>}
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ParentAttendanceTab({ session, athlete }) {
  const [month, setMonth] = useState(() => todayISO().slice(0, 7));
  const [events, setEvents] = useState([]);
  const [records, setRecords] = useState({});
  const [startedMap, setStartedMap] = useState({});
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      setLoading(true); setError('');
      try {
        const [start, end] = monthRange(month);
        const evs = await pg(`/events?team_id=eq.${athlete.team_id}&date=gte.${start}&date=lte.${end}&select=*&order=date.desc`, session.accessToken);
        setEvents(evs);
        if (evs.length > 0) {
          const ids = evs.map((e) => e.id).join(',');
          const att = await pg(`/attendance?athlete_id=eq.${athlete.id}&event_id=in.(${ids})&select=*`, session.accessToken);
          const map = {};
          (att || []).forEach((r) => { map[r.event_id] = r; });
          setRecords(map);

          const started = await pg('/rpc/events_started_map', session.accessToken, {
            method: 'POST',
            body: { event_ids: evs.map((e) => e.id) },
          });
          const startedM = {};
          (started || []).forEach((s) => { startedM[s.event_id] = s.started; });
          setStartedMap(startedM);
        } else { setRecords({}); setStartedMap({}); }
      } catch (e) { setError(e.message); } finally { setLoading(false); }
    })();
  }, [session, athlete, month]);

  const today = todayISO();
  const pastEvents = events.filter((e) => e.date <= today);
  const presentCount = pastEvents.filter((e) => records[e.id]?.present).length;
  const pct = pastEvents.length ? Math.round((presentCount / pastEvents.length) * 100) : 0;

  return (
    <div className="px-4 pt-4">
      <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold mb-0.5">{athlete.name}</div>
      <div className="text-xs mb-4" style={{ color: 'var(--gdc-grey)' }}>{athlete.teams?.name}</div>
      <MonthNav month={month} onChange={setMonth} />
      <ErrorBlock message={error} />
      <Card className="mb-4">
        <div className="flex items-center justify-between mb-2"><div className="text-sm font-semibold">Assiduidade do mês</div><Badge tone={pct >= 75 ? 'green' : pct >= 50 ? 'amber' : 'red'}>{pct}%</Badge></div>
        <div className="h-2 rounded-full overflow-hidden"><div className="h-full rounded-full" style={{ width: `${pct}%`, background: pct >= 75 ? '#22C55E' : pct >= 50 ? '#FB923C' : '#EF4444' }} /></div>
        <div className="text-xs mt-2" style={{ color: 'var(--gdc-grey)' }}>{presentCount} de {pastEvents.length} treinos/jogos já realizados</div>
        <div className="text-[11px] mt-1" style={{ color: 'var(--gdc-grey)' }}>Só conta treinos/jogos até hoje — eventos futuros não entram no cálculo.</div>
      </Card>
      {loading ? <LoadingBlock /> : pastEvents.length === 0 ? <Empty icon={Calendar} title="Sem treinos/jogos já realizados neste mês" /> : (
        <div className="flex flex-col gap-2">
          {pastEvents.map((ev) => {
            const rec = records[ev.id];
            const statusBadge = rec?.present
              ? <Badge tone="green">Presente</Badge>
              : startedMap[ev.id]
                ? <Badge tone="grey">Ausente</Badge>
                : <Badge tone="amber">Por marcar</Badge>;
            return (
              <Card key={ev.id}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: ev.type === 'Jogo' ? 'rgba(255,199,44,0.22)' : 'rgba(11,11,12,0.06)' }}>
                      {ev.type === 'Jogo' ? <Swords size={15} color="var(--gdc-yellow-deep)" /> : <Dumbbell size={15} color="var(--gdc-grey)" />}
                    </div>
                    <div><div className="font-semibold text-sm">{ev.label}</div><div className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{fmtDate(ev.date)}</div></div>
                  </div>
                  {statusBadge}
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ParentBehaviorTab({ session, profile, athlete }) {
  const [records, setRecords] = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [error, setError] = useState('');
  const [showIncident, setShowIncident] = useState(false);

  const load = useCallback(async () => {
    setError('');
    try {
      const [attRows, incRows] = await Promise.all([
        pg(`/attendance?athlete_id=eq.${athlete.id}&present=eq.true&select=*,events(*)`, session.accessToken),
        pg(`/incidents?athlete_id=eq.${athlete.id}&select=*&order=date.desc`, session.accessToken),
      ]);
      setRecords((attRows || []).filter((r) => r.behavior && r.events).sort((a, b) => (b.events.date || '').localeCompare(a.events.date || '')));
      setIncidents(incRows);
    } catch (e) { setError(e.message); }
  }, [session, athlete]);

  useEffect(() => { load(); }, [load]);

  const addIncident = async (description) => {
    await pg('/incidents', session.accessToken, {
      method: 'POST',
      body: { athlete_id: athlete.id, description, created_by: profile.id, created_by_role: 'parent' },
      prefer: 'return=representation',
    });
    setShowIncident(false);
    load();
  };

  return (
    <div className="px-4 pt-4">
      <div className="flex items-center justify-between mb-4">
        <div style={{ fontFamily: 'var(--font-display)' }} className="text-xl font-bold">Comportamento</div>
        <Button size="sm" icon={Plus} onClick={() => setShowIncident(true)}>Comunicar</Button>
      </div>
      <ErrorBlock message={error} />
      <div className="font-bold text-sm mb-2">Comunicadas por ti / pelo treinador</div>
      {incidents.length === 0 ? <div className="text-sm py-4 text-center mb-6" style={{ color: 'var(--gdc-grey)' }}>Sem incidências registadas.</div> : (
        <div className="flex flex-col gap-2 mb-6">
          {incidents.map((i) => (
            <Card key={i.id}>
              <div className="flex items-center justify-between mb-1">
                <Badge tone="amber">{fmtDate(i.date)}</Badge>
                <span className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{i.created_by_role === 'parent' ? 'Tu' : 'Treinador'}</span>
              </div>
              <div className="text-sm">{i.description}</div>
            </Card>
          ))}
        </div>
      )}
      <div className="font-bold text-sm mb-2">Avaliação nos treinos/jogos</div>
      {records.length === 0 ? <div className="text-sm py-4 text-center" style={{ color: 'var(--gdc-grey)' }}>Ainda sem avaliações.</div> : (
        <div className="flex flex-col gap-2">
          {records.map((r) => (
            <Card key={r.id}>
              <div className="flex items-center justify-between">
                <div><div className="font-semibold text-sm">{r.events.label}</div><div className="text-xs" style={{ color: 'var(--gdc-grey)' }}>{fmtDate(r.events.date)}</div></div>
                <Badge tone={r.behavior === 'Bom' ? 'green' : r.behavior === 'Razoável' ? 'amber' : 'red'}>{r.behavior}</Badge>
              </div>
            </Card>
          ))}
        </div>
      )}
      {showIncident && <IncidentModal onClose={() => setShowIncident(false)} onSubmit={addIncident} />}
    </div>
  );
}
